def parse_location(location: str):
    """Get the x, y position (microns) from an OptogeneticStimulusSite location, e.g.
    "x=102554 um, y=7769 um (scanner coordinates)", or from older files,
    "(np.int32(102554), np.int32(7769))" or "[0, 0]"
    """
    numbers = re.findall(r"-?\d+\.?\d*", location.replace("np.int32", ""))
    return np.array([float(numbers[0]), float(numbers[1])])


@dataclass()
class acq4_data:  # dataclass to hold the data from a single acq4 protocol
    nwb_name: str = ""  # name of the nwb file
    protocol: str = ""  # name of the acq4 protocol in this data set
    mode: str = ""  # recording mode
    nsweeps: int = 0  # number of sweeps
    sample_rate: float = 0.0  # sample rate of the recording (Hz)
    start_time: float = 0.0  # start of the first sweep, relative to the session start (s)
    response: object = None  # response data  # (becomes np.ndarray later)
    command: object = None  # electrical command data
    ostim: object = None  # optical stimulus data
    ostim_timebase: object = None  # timebase for optical stimulus
    optospots: object = None  # optical spot data
    ospot_size: float = 0.0  # optical spot size (m)
    timebase: object = None
    laser_command: object = None
    laser_timebase: object = None


class ReadNWB:
    def __init__(self, filename: Union[str, Path, None] = None):
        self.protocols = {}
        self.info = {}
        self.fig = None
        self.pick_cid = None  # connection for picking stimulus spots in the map
        if filename is None:
            return
        else:
            self.readfile(f=filename)

    def split_acqname(self, acqname: str):
        """_summary_
        acquisition names:
            'Vc_LED_stim_single_000_Ics1_0'
            split to protocol, name, sweep, and get the recording mode from the comments field.

        Params
        ------
            acqname (str): acquisition name

        Returns
        -------
        Tuple[str, str, str, str]: protocol, sweep, protonum, recmode
        """
        # print("acqname: ", acqname)
        acqdict = acq_re.match(acqname).groupdict()
        recmode = self.nwbfile.acquisition[acqname].comments
        return acqdict["protocol"], acqdict["sweep"], acqdict["name"], recmode

    def split_stimname(self, stimname: str):
        """_summary_
        stimulus names:
            'Vc_LED_stim_single_000:ChR2 Stimulation, LED 470 nm, sweep=0
            split to protocol, name, sweep, and get the recording mode from the comments field.

        Params
        ------
            acqname (str): acquisition name

        Returns
        -------
        Tuple[str, str, str, str]: protocol, sweep, protonum, recmode
        """
        recmode = self.nwbfile.stimulus[stimname].comments
        stim = estim_re.match(stimname)
        if stim is None:
            print(f"Stimulus name {stimname} did not match expected pattern.")
            return None, recmode
        stimdict = stim.groupdict()
        if stimdict["name"].startswith("opto"):  # older files: separate optical waveform series
            stimdict["stimtype"] = "optical"
        elif stimdict["name"].startswith("OptoSeries"):  # OptoSeries (laser) or OptoSeriesLED
            stimdict["stimtype"] = "OptoSeries"
        else:
            stimdict["stimtype"] = "electrical"
        # print("stimdict: ", stimdict)
        return (
            stimdict,
            recmode,
        )

    def get_optical_stimulus(self, nwbfile, optostim: Union[str, None], optospot: Union[str, None]):
        """Get the optical stimulus waveform and spot location for one sweep.
        The waveform is held in the OptogeneticSeries (optospot); older files held it
        in a separate '<protocol>:opto_N' stimulus series (optostim).

        Returns
        -------
        Tuple: waveform (np.ndarray), location (np.ndarray: x, y in microns),
            and the series holding the waveform; all None if there is no optical stimulus
        """
        if optospot is None:
            return None, None, None
        spot_series = nwbfile.stimulus[optospot]
        wave_series = nwbfile.stimulus[optostim] if optostim is not None else spot_series
        location = parse_location(spot_series.site.location)
        return np.array(wave_series.data), location, wave_series

    def readfile(self, f: Union[Path, str, None] = None):
        """Read all of the protocols in an NWB file into self.protocols
        (a dict of acq4_data, keyed by protocol name, in the order they were recorded).
        The file is closed after reading; the data are held in memory.

        Params
        ------
            f (Union[Path, str, None], optional): File path. Defaults to None.

        Returns
        -------
        Nothing
        """
        self.filename = f
        self.protocols = {}
        self.info = {}
        if not Path(f).is_file():
            print(f"File {f!s} not found.")
            return
        with NWBHDF5IO(str(f), mode="r") as io:
            nwbfile = io.read()
            self.nwbfile = nwbfile
            self.info = self.get_file_info(nwbfile)
            if len(nwbfile.acquisition) == 0:
                print("No acquisition data found.")
                return

            # get all of the stimulation data in the nwb file
            e_stimdict = {}
            o_stimdict = {}
            o_spotdict = {}
            for stim in nwbfile.stimulus.keys():
                stimdict, recmode = self.split_stimname(stim)
                if stimdict is None:
                    continue
                if stimdict["stimtype"] == "electrical":
                    e_stimdict[(stimdict["protocol"], stimdict["sweep"])] = stim
                elif stimdict["stimtype"] == "optical":
                    o_stimdict[(stimdict["protocol"], stimdict["sweep"])] = stim
                elif stimdict["stimtype"] == "OptoSeries":
                    # if both laser and LED were used, show the laser
                    key = (stimdict["protocol"], stimdict["sweep"])
                    if key not in o_spotdict or stimdict["name"] == "OptoSeries":
                        o_spotdict[key] = stim
            # electrical stimulus (currents in current-clamp, voltages in voltage clamp)
            # and optical stimuli (if they exist) are paired within a protocol with the
            # acquistion of voltage or current.
            # The pairing is uniquely matched up by protocol name (unique) and sweep number.

            # group the acquisitions by protocol, in sweep order
            acq_by_protocol = {}
            for acq in nwbfile.acquisition.keys():
                acqmatch = acq_re.match(acq)
                if acqmatch is None:
                    print(f"Acquisition name {acq} did not match expected pattern.")
                    continue
                acq_by_protocol.setdefault(acqmatch["protocol"], []).append(
                    (int(acqmatch["sweep"]), acq)
                )
            for protocol_name, sweeps in acq_by_protocol.items():
                self.protocols[protocol_name] = self.read_protocol(
                    nwbfile,
                    protocol_name=protocol_name,
                    acquisitions=[acq for _, acq in sorted(sweeps)],
                    e_stimdict=e_stimdict,
                    o_stimdict=o_stimdict,
                    o_spotdict=o_spotdict,
                )
            # present the protocols in the order they were recorded
            self.protocols = dict(
                sorted(self.protocols.items(), key=lambda item: item[1].start_time)
            )
        self.nwbfile = None  # the file is closed

    def get_file_info(self, nwbfile) -> dict:
        """Get the session and subject information to show with the data"""
        info = {
            "session_id": nwbfile.session_id,
            "session_start": str(nwbfile.session_start_time),
            "session_description": nwbfile.session_description,
            "notes": nwbfile.notes,
        }
        subject = nwbfile.subject
        if subject is not None:
            info.update(
                {
                    "subject_id": subject.subject_id,
                    "age": subject.age,
                    "sex": subject.sex,
                    "weight": subject.weight,
                    "genotype": subject.genotype,
                    "subject_description": subject.description,
                }
            )
        return info

    def read_protocol(
        self,
        nwbfile,
        protocol_name: str,
        acquisitions: list,
        e_stimdict: dict,
        o_stimdict: dict,
        o_spotdict: dict,
    ):
        """Read the data for one protocol into an acq4_data object

        Params
        ------
            nwbfile: the open NWB file
            protocol_name (str): the acq4 protocol name
            acquisitions (list): the acquisition names for this protocol, in sweep order
            e_stimdict, o_stimdict, o_spotdict (dict): stimulus names, keyed by (protocol, sweep)

        Returns
        -------
        acq4_data
        """
        first = nwbfile.acquisition[acquisitions[0]]
        protocol = acq4_data(
            nwb_name=acquisitions[0],
            protocol=protocol_name,
            mode=first.comments,
            nsweeps=len(acquisitions),
            sample_rate=first.rate,
            start_time=first.starting_time if first.starting_time is not None else 0.0,
        )
        responses, commands, ostims, ostim_timebases, spots = [], [], [], [], []
        for acq in acquisitions:
            sweep = acq_re.match(acq)["sweep"]
            key = (protocol_name, sweep)
            response = np.array(nwbfile.acquisition[acq].data)
            responses.append(response)
            estim = e_stimdict.get(key, None)
            if estim is not None:
                commands.append(np.array(nwbfile.stimulus[estim].data))
            else:
                commands.append(np.zeros_like(response))
            optostimdata, location, optostim_series = self.get_optical_stimulus(
                nwbfile, o_stimdict.get(key, None), o_spotdict.get(key, None)
            )
            if optostimdata is not None:
                ostims.append(optostimdata)
                ostim_timebases.append(np.arange(optostimdata.shape[0]) / optostim_series.rate)
                spots.append(location)
                # spot size (m) is stored in the comments as "Spotsize: 1.0e-04" (or just the number)
                protocol.ospot_size = float(optostim_series.comments.split(":")[-1])
        protocol.response = np.vstack(responses)
        protocol.command = np.vstack(commands)
        protocol.timebase = np.arange(protocol.response.shape[1]) / protocol.sample_rate
        if len(ostims) > 0:
            protocol.ostim = np.vstack(ostims)
            protocol.ostim_timebase = np.vstack(ostim_timebases)
            protocol.optospots = np.vstack(spots)
        return protocol

    def onpick(self, event):
        """Show the trace for the stimulus spot that was clicked in the map"""
        index = int(event.ind[0])
        self.trace_plot[0].set_ydata(self.response[index])
        self.ELabel.set_text(f"Trace {index:d}")
        self.axs["E"].relim()
        self.axs["E"].autoscale_view()
        self.fig.canvas.draw_idle()

    def plot_traces(
        self,
        protocol: acq4_data,
        fig: Union[Figure, None] = None,
        nprotocols: int = 1,
        protocol_number: int = 1,
    ):
        """Minimal plotter to show the data in an nwb file generated by acq4_to_nwb.py

        Params
        ------
            protocol (acq4_data): the protocol to plot
            fig (matplotlib Figure, optional): the figure to draw into (it is cleared first).
                If None, a new figure is made.

        Returns
        -------
        the matplotlib Figure
        """
        if fig is None:
            fig = mpl.figure(figsize=(8, 10), layout="constrained")
        else:
            fig.clear()
        if self.pick_cid is not None and self.fig is not None:
            self.fig.canvas.mpl_disconnect(self.pick_cid)
            self.pick_cid = None
        axs = fig.subplot_mosaic(
            [["A", "D"], ["A", "D"], ["A", "D"], ["A", "D"], ["B", "E"], ["C", "F"]],
        )
        self.fig = fig
        self.axs = axs
        self.response = protocol.response
        for ax in ["A", "B", "C", "E", "F"]:
            axs[ax].spines["right"].set_visible(False)
            axs[ax].spines["top"].set_visible(False)
        fn = "/".join(str(self.filename).split("/")[-2:])
        fig.suptitle(
            f"{fn:s}  {protocol.protocol:s} (#{protocol_number}/{nprotocols})",
            fontsize=8,
            fontweight="demibold",
        )
        current_clamp = protocol.mode.lower() in ["cc", "ic"]
        delta_I = 0.075 if current_clamp else 100e-12  # offset between stacked traces

        for i in range(protocol.response.shape[0]):
            axs["A"].plot(protocol.timebase, protocol.response[i, :] + i * delta_I, linewidth=0.33)
            axs["B"].plot(protocol.timebase, protocol.command[i, :], linewidth=0.33)

            if protocol.ostim is not None:
                axs["C"].plot(protocol.ostim_timebase[i, :], protocol.ostim[i, :], linewidth=0.5)
        axs["F"].plot(protocol.timebase, np.mean(protocol.response, axis=0), linewidth=0.5)
        self.trace_plot = axs["E"].plot(
            protocol.timebase, protocol.response[0, :], "g-", linewidth=0.5
        )
        self.ELabel = self.axs["E"].text(
            0.05, 0.95, f"Trace: {0:d}", ha="left", va="top", transform=self.axs["E"].transAxes
        )
        axs["A"].set_xlabel("T (s)")
        axs["F"].set_xlabel("T (s)")
        if current_clamp:
            axs["A"].set_ylabel("V (V)")
            axs["B"].set_ylabel("I (A)")
            axs["F"].set_ylabel("mean V (V)")
        else:
            axs["A"].set_ylabel("I (A)")
            axs["B"].set_ylabel("V (V)")
            axs["F"].set_ylabel("mean I (A)")
        if protocol.ostim is not None:
            axs["C"].set_xlabel("T (s)")
            axs["C"].set_ylabel("Light command (V)")

        # draw a map of the stimulus positions, colored by the response
        # (only if the light was aimed at more than one position)
        if protocol.ostim is None:
            for ax in ["C", "D"]:
                axs[ax].set_axis_off()
            axs["D"].text(0.5, 0.5, "No optical stimulation", ha="center", va="center", transform=axs["D"].transAxes)
        elif len(np.unique(protocol.optospots, axis=0)) == 1:
            axs["D"].set_axis_off()
            axs["D"].text(0.5, 0.5, "Widefield stimulation\n(one position)", ha="center", va="center", transform=axs["D"].transAxes)
        else:
            opos = protocol.optospots
            osize = protocol.ospot_size * 1e3  # spot size (m) to mm, to match the positions
            patches = []
            # create a circle to show the position of each stimulus
            for isp in range(opos.shape[0]):
                circle = mpatches.Circle(
                    (opos[isp, 0] / 1e3, opos[isp, 1] / 1e3),  # microns to mm
                    radius=osize / 2.0,
                    color="blue",
                    ec="none",
                )
                patches.append(circle)
            collection = PatchCollection(patches, cmap=mpl.cm.cool, alpha=0.6)
            # response in a 20 ms window after the light onset, relative to the 20 ms before
            ostim0 = protocol.ostim[0, :]
            onset = np.argmax(ostim0 > 0.5 * np.max(ostim0)) if np.max(ostim0) > 0 else 0
            istim = int(protocol.ostim_timebase[0, onset] * protocol.sample_rate)
            twentyms = int(0.020 * protocol.sample_rate)
            istim = min(max(istim, twentyms), protocol.response.shape[1] - twentyms)
            colors = np.mean(protocol.response[:, istim : istim + twentyms], axis=1) - np.mean(
                protocol.response[:, istim - twentyms : istim], axis=1
            )
            if np.max(np.abs(colors)) > 0:
                colors = colors / np.max(np.abs(colors))
            collection.set_array(colors)
            collection.set_picker(True)
            axs["D"].add_collection(collection, autolim=True)
            axs["D"].set_facecolor("white")
            axs["D"].set_aspect("equal")
            axs["D"].autoscale_view()
            axs["D"].set_xlabel("x (mm)")
            axs["D"].set_ylabel("y (mm)")
            self.pick_cid = fig.canvas.mpl_connect("pick_event", self.onpick)
        return fig


def main():

    parser = argparse.ArgumentParser(description="Display an NWB file")
    parser.add_argument(dest="inputfile", type=str, help="input filename")
    args = parser.parse_args()
    if not Path(args.inputfile).is_file():
        print(f"File {args.inputfile} not found.")
        exit(1)
    R = ReadNWB(args.inputfile)
    nprotocols = len(R.protocols)
    # one window per protocol, shown in turn
    for k, protocol in enumerate(R.protocols.values(), start=1):
        R.plot_traces(protocol, nprotocols=nprotocols, protocol_number=k)
        mpl.show()


if __name__ == "__main__":
    main()
